	defer rows.Close()
	for rows.Next() {
		dst = append(dst, FeedRow{})
		if err := scanFeed(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	return dst, rows.Err()
